//! The API's wire types (`ctxloom.v1`, one versioned package for the
//! daemon, its sessions and the library, OQ-1): prost messages generated from
//! `proto/ctxloom/v1`. A `HandleSync` projection is the resource
//! message the matching `Get` returns (daemon.proto's header): a read model
//! answers its view as one of these (S32).
//!
//! Every message is also its proto3 JSON (ruling 146, OQ-21): serde impls
//! generated by pbjson-build, proto field names kept, a default left out,
//! an enum by its value's name, a 64-bit integer as a decimal string. The
//! well-known types the package uses are this crate's own
//! ([`google::protobuf`]), with their JSON mapping written by hand
//! (`wkt.rs`): a `Timestamp` RFC 3339 in UTC, a `Value` the JSON value it
//! holds, whatever its kind (a free-form document, OQ-11), a `Struct` the
//! object itself (its keys sorted), a `FieldMask` its paths in one string.

/// The generated package, nested as its proto package is.
pub mod ctxloom {
    // Generated: the request oneofs carry whole messages (a launch beside a
    // word), as the drafts define them.
    #[allow(clippy::large_enum_variant)]
    pub mod v1 {
        include!(concat!(env!("OUT_DIR"), "/json/ctxloom.v1.rs"));
        // Generated by pbjson-build.
        #[allow(
            clippy::all,
            clippy::pedantic,
            clippy::nursery,
            clippy::cognitive_complexity,
            missing_docs
        )]
        mod serde_impls {
            use super::*;
            include!(concat!(env!("OUT_DIR"), "/json/ctxloom.v1.serde.rs"));
        }
    }
}

